import pandas as pd
import random
from datetime import datetime

def task_func(
    task_list,
    n_tasks,
    employees=["John Doe", "Jane Smith", "James Brown", "Mary Johnson", "Robert Davis"],
    seed=None,
):
    if n_tasks < 0:
        raise ValueError("n_tasks cannot be negative")

    if seed is not None:
        random.seed(seed)

    if not task_list:
        if n_tasks == 0:
            df = pd.DataFrame(columns=['Task Name', 'Assigned To', 'Due Date'])
            return df
        else:
            raise ValueError("task_list cannot be empty when n_tasks > 0")

    if not employees:
        if n_tasks == 0:
            df = pd.DataFrame(columns=['Task Name', 'Assigned To', 'Due Date'])
            return df
        else:
            raise ValueError("employees list cannot be empty when n_tasks > 0")

    due_date = datetime.now().strftime('%Y-%m-%d')

    # Select n_tasks tasks randomly from task_list (with replacement)
    selected_tasks = random.choices(task_list, k=n_tasks)

    # Assign each task to a random employee
    assignments = []
    for task in selected_tasks:
        # Normalize task name: replace spaces with underscores
        normalized_task = task.replace(' ', '_')
        assigned_to = random.choice(employees)
        assignments.append({
            'Task Name': normalized_task,
            'Assigned To': assigned_to,
            'Due Date': due_date
        })

    df = pd.DataFrame(assignments, columns=['Task Name', 'Assigned To', 'Due Date'])
    return df

